column3:
curl -X POST \ 
   'https://api.weglot.com/translate?api_key=my_api_key' \ 
   -H 'Content-Type: application/json' \ 
   -d '{   
    "l_from":"en", 
    "l_to":"fr", 
    "request_url":"https://www.website.com/", 
    "words":[   
       {"w":"This is a blue car", "t": 1}, 
       {"w":"This is a black car", "t": 1} 
    ] 
 }'
